   107	                if (!React.isValidElement(child)) {
   108	                    return child;
   109	                }
   110	
   111	                type ChildComponentProps = ChildrenProps & {style?: AllStyles};
   112	                const childProps = child.props as ChildComponentProps;
   113	                const props: StrikethroughProps = {
   114	                    style: StyleUtils.combineStyles(childProps.style ?? [], styles.offlineFeedback.deleted, styles.userSelectNone),
   115	                };
   116	
